import sys, string

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    R = int(data)
    letters = string.ascii_uppercase
    lines = []
    for i in range(1, R + 1):
        lines.append(' '.join(letters[:i]))
    sys.stdout.write('\n'.join(lines))

if __name__ == "__main__":
    main()
